// job-ingest answers with ONE item carrying the whole queue. Fan it out so each
// application is its own item — one refused send then costs one email, not the
// whole pass.
const res = $input.first().json;
if (!res || res.ok !== true) {
  throw new Error('job-ingest notify_queue failed: ' + JSON.stringify(res).slice(0, 300));
}
const notify = res.notify || [];

// An empty queue is the normal steady state, not a failure: it means every scored
// application has already been mailed. Returning [] ends the run quietly. Throwing
// would paint a red execution every 15 minutes and train everyone to ignore them —
// and then the one that mattered would look exactly like the others.
if (notify.length === 0) return [];

return notify.map((n) => ({ json: n }));

__NOTIFY_JS__

// --- node body ---
// One decision email per queued application, built by the tested
// buildDecisionEmail rather than by string concatenation here: every field below
// (title, company, location, the ad URL) was written by whoever posted the job, and
// it all ends up in an HTML body and a mail header.
//
// The recipient is the user's OWN inbox. This workflow never mails a company — that
// is job-apply, and keeping the two in separate workflows is deliberate.
const TO = $env.JOB_NOTIFY_TO || 'bastianrthomsen@gmail.com';

const out = [];
for (const item of $input.all()) {
  const app = item.json || {};
  const mail = buildDecisionEmail(app);
  out.push({
    json: {
      application_id: app.application_id,
      to: TO,
      subject: mail.subject,
      html: mail.html,
      // n8n's Gmail node sends a single body part, so only `html` is transmitted
      // today. `text` is the text/plain half a raw-MIME sender would attach, and it
      // is what the tests pin the email's *content* against independently of its
      // markup. Carrying it makes multipart a one-line change if that node gains it.
      text: mail.text,
    },
  });
}
return out;

__NOTIFY_JS__

// --- node body ---
// Reached only from the Gmail node's SUCCESS output. notify_result flips the row to
// needs_approval server-side, so posting it for an email that never left would mark
// a job "waiting for you" that you will never actually see.
//
// Pairing is by pairedItem, not by position. The error output pulls failed items
// out of this stream, so output-0 index i stops being upstream index i the moment
// one send fails — and that offset would stamp a Gmail message id onto the WRONG
// application. pairedSourceIndex falls back to the index, which is correct whenever
// nothing failed.
const composed = $('Build Decision Email').all();

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const sent = items[i].json || {};
  const src = composed[pairedSourceIndex(items[i].pairedItem, i)];
  const applicationId = src && src.json ? src.json.application_id : null;

  // No id, no claim. Silently skipping is right here: the row stays in draft and
  // comes back next pass, which is strictly better than marking something sent on
  // a guess.
  if (!applicationId) continue;

  // Gmail's message resource: `id` is the message, `threadId` the conversation.
  out.push({
    json: {
      action: 'notify_result',
      user_id: $env.NEXUS_USER_ID,
      application_id: applicationId,
      ok: true,
      message_id: sent.id || sent.messageId || null,
    },
  });
}
return out;

// A failed send is not a failed run.
//
// notify_result is posted ONLY from the success output, so a row whose email did
// not leave the machine keeps status 'draft' and the next 15-minute pass picks it
// up again. That is the retry. Do not add another one here: Gmail can fail *after*
// accepting a message, and a retry loop that cannot tell those apart is how the
// same decision email arrives four times.
const failed = $input.all();
for (const item of failed) {
  const j = item.json || {};
  const err = j.error || j.message || j;
  console.log(
    'decision email failed, row left in draft for the next pass: ' +
      JSON.stringify(err).slice(0, 300),
  );
}
return [];
